/**
 * Admin-Generated Secure Password Reset Engine
 * Balananda Vaidik Sewa
 * 
 * Implements single-use, cryptographically secure password reset links
 * generated by Super Admin without exposing tokens or passwords in logs.
 */

import crypto from 'crypto';
import fs from 'fs';
import path from 'path';
import { hashUserPassword } from './authEngine';

export interface PasswordResetTokenRecord {
  id: string;
  userId: string;
  tokenHash: string; // SHA-256 hash of the plaintext token (never plaintext!)
  createdBy: string;
  createdAtISO: string;
  expiresAtISO: string;
  used: boolean;
  usedAtISO?: string;
}

const LOCAL_RESET_TOKENS_FILE = path.join(process.cwd(), 'data', 'password_reset_tokens.json');

export class PasswordResetEngine {
  private static instance: PasswordResetEngine;
  private tokens: PasswordResetTokenRecord[] = [];

  private constructor() {
    this.loadFromDisk();
  }

  public static getInstance(): PasswordResetEngine {
    if (!PasswordResetEngine.instance) {
      PasswordResetEngine.instance = new PasswordResetEngine();
    }
    return PasswordResetEngine.instance;
  }

  private loadFromDisk(): void {
    try {
      if (fs.existsSync(LOCAL_RESET_TOKENS_FILE)) {
        this.tokens = JSON.parse(fs.readFileSync(LOCAL_RESET_TOKENS_FILE, 'utf-8'));
      }
    } catch {
      this.tokens = [];
    }
  }

  private persist(): void {
    try {
      const dir = path.dirname(LOCAL_RESET_TOKENS_FILE);
      if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true });
      fs.writeFileSync(LOCAL_RESET_TOKENS_FILE, JSON.stringify(this.tokens, null, 2), 'utf-8');
    } catch (e) {
      console.warn('[PasswordResetEngine] Failed to persist tokens:', e);
    }
  }

  /**
   * Super Admin: Generate a secure, single-use password reset link for a specific user
   */
  public generateResetLink(params: {
    userId: string;
    adminUsername: string;
    frontendBaseUrl?: string;
    expiresMinutes?: number;
  }): {
    success: boolean;
    rawToken: string;
    resetUrl: string;
    expiresAtISO: string;
    expiresMinutes: number;
    tokenRecord: PasswordResetTokenRecord;
  } {
    const expiresMinutes = params.expiresMinutes || 20;
    const now = new Date();
    const expiresAt = new Date(now.getTime() + expiresMinutes * 60 * 1000);

    // 1. Invalidate any existing unused reset tokens for this user
    for (const t of this.tokens) {
      if (t.userId === params.userId && !t.used) {
        t.used = true;
        t.usedAtISO = now.toISOString();
      }
    }

    // 2. Generate cryptographically secure random token (32 bytes = 64 hex chars)
    const rawToken = crypto.randomBytes(32).toString('hex');

    // 3. Store ONLY the SHA-256 hash of the token
    const tokenHash = crypto.createHash('sha256').update(rawToken).digest('hex');

    const tokenRecord: PasswordResetTokenRecord = {
      id: `prt_${Date.now()}_${crypto.randomBytes(3).toString('hex')}`,
      userId: params.userId,
      tokenHash,
      createdBy: params.adminUsername,
      createdAtISO: now.toISOString(),
      expiresAtISO: expiresAt.toISOString(),
      used: false
    };

    this.tokens.unshift(tokenRecord);
    this.persist();

    const baseUrl = params.frontendBaseUrl || 'https://balananda-vaidik-sewa.web.app';
    const resetUrl = `${baseUrl}/#reset-password?token=${rawToken}`;

    return {
      success: true,
      rawToken,
      resetUrl,
      expiresAtISO: expiresAt.toISOString(),
      expiresMinutes,
      tokenRecord
    };
  }

  /**
   * User: Validate token and update user password securely
   */
  public verifyToken(rawToken: string): {
    valid: boolean;
    userId?: string;
    message?: string;
    tokenRecord?: PasswordResetTokenRecord;
  } {
    if (!rawToken || typeof rawToken !== 'string') {
      return { valid: false, message: 'अवैध वा छुटेको रिसेट टोकन।' };
    }

    const tokenHash = crypto.createHash('sha256').update(rawToken.trim()).digest('hex');
    const record = this.tokens.find(t => t.tokenHash === tokenHash);

    if (!record) {
      return { valid: false, message: 'यो पासवर्ड रिसेट लिङ्क अवैध वा फेला नपरेको छ।' };
    }

    if (record.used) {
      return { valid: false, message: 'यो पासवर्ड रिसेट लिङ्क पहिले नै प्रयोग भइसकेको छ। कृपया नयाँ लिङ्क अनुरोध गर्नुहोस्।' };
    }

    if (new Date(record.expiresAtISO).getTime() < Date.now()) {
      return { valid: false, message: 'यो पासवर्ड रिसेट लिङ्कको म्याद समाप्त भइसकेको छ (२० मिनेट मात्र मान्य)।' };
    }

    return { valid: true, userId: record.userId, tokenRecord: record };
  }

  /**
   * Mark token as used upon successful password reset
   */
  public markTokenUsed(rawToken: string): boolean {
    const tokenHash = crypto.createHash('sha256').update(rawToken.trim()).digest('hex');
    const record = this.tokens.find(t => t.tokenHash === tokenHash);
    if (record) {
      record.used = true;
      record.usedAtISO = new Date().toISOString();
      this.persist();
      return true;
    }
    return false;
  }
}

export const passwordResetEngine = PasswordResetEngine.getInstance();
